import{_ as i,c as n,o as a,al as r,am as t,an as d}from"./chunks/framework.CJHIn2TN.js";const g=JSON.parse('{"title":"Architektur","description":"","frontmatter":{},"headers":[],"relativePath":"de/architecture.md","filePath":"de/architecture.md"}'),s={name:"de/architecture.md"};function h(u,e,c,l,o,m){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="architektur" tabindex="-1">Architektur <a class="header-anchor" href="#architektur" aria-label="Permalink to “Architektur”">​</a></h1><p>Um Verständnis dafür zu bekommen, wie und was ich erbaut habe, musst Du Dich mit der Architektur dieses &quot;Frameworks&quot; auseinander setzen. Ich nenne es ganz bewusst Framework. Das liegt daran, dass ich es noch nicht beendet habe und auch noch nicht weiß, wohin mich diese Reise führt. Beim spielen hat man oft die besten Ideen.</p><p>Ich bin kein Freund des Begriffes &quot;Architektur&quot;. Mir fällt nur leider kein anderer Name ein um Dir eine Übersicht aller Funktionen auf einmal zu erklären.</p><p>An einem Bild, kannst Du meine Entwicklungsschritte im Detail verfolgen:</p><p><a href="/images/architecture.png" target="_blank"><img src="'+t+'" alt="Architecture"></a></p><ul><li>In gestricheltem Rahmen siehst Du Module in der Hardware als auch in der Software Ausprägung, die sich noch im Aufbau bzw. in der Planung befinden.</li><li>Realisiert wurde der übrige Teil.</li></ul><h2 id="hardware" tabindex="-1">Hardware <a class="header-anchor" href="#hardware" aria-label="Permalink to “Hardware”">​</a></h2><p>Damit ich über die Zeit die Möglichkeit habe, die Funktionalität zu erweitern, habe ich mich für ein Modulares Design entschieden. Im Bereich <a href="/de/modules/">Module</a> findest Du eine Übersicht der einzelnen Module mit ihrer jeweiligen Funktion(en). Unabhängig von der Hardware ist jedes Modul auch mit einer Firmware ausgerüstet die Steuerungsaufgaben entgegen nimmt und auch Daten an die Software zurück sendet.</p><p>Untereinander und übergeordnet zur Software, erfolgt die Kommunikation über einen CAN Bus mit einer Datenrate von 250kbps. Für mich hat der CAN Bus jede Menge Vorteile die ich nicht einzeln ausführen möchte. Da er extrem Robust ist und einfach innerhalb der Module an einen Controller anzubinden ist, habe ich mich dafür entschieden.</p><h2 id="software" tabindex="-1">Software <a class="header-anchor" href="#software" aria-label="Permalink to “Software”">​</a></h2><p>Die Software ist ebenfalls Modular aufgebaut. Der Gedanke das einzelne Funktionalitäten mit vortschreitender Entwicklung dazu kommen dürfen, gefällt mir sehr gut. Weiteres findest Du im Bereich: <a href="/de/topping/">Topping</a>.</p><h2 id="verbindung" tabindex="-1">Verbindung <a class="header-anchor" href="#verbindung" aria-label="Permalink to “Verbindung”">​</a></h2><p>Die Software bindet die einzelnen Module über einen CAN-USB Adapter ein. Dadurch habe ich die Möglichkeit mit allen Modulen nahezu Gleichzeitig zu kommunizieren. Außerdem kann ich über den CAN-Bus auch die Firmware der einzelnen Module updaten. Das gibt mir immense Freiheiten da ich nicht jedesmal ein Modul aus dem Rack nehmen muss.</p><h2 id="rack" tabindex="-1">Rack <a class="header-anchor" href="#rack" aria-label="Permalink to “Rack”">​</a></h2><p>Hier siehst Du das Rack im aktuellen Entwicklungsstand mit den (November 2025) realisierten Modulen:</p><p><a href="/images/rack_2025_11.jpg" target="_blank"><img src="'+d+'" alt="Logo"></a></p><p>Die Rack-Schubladen unten habe ich erstmal weg gelassen. In ihnen sind Sensoren, Schalter, Leitungen, Lichtschranken, Magnete usw. untergebracht. Wenn ich sie etwas besser aufgeräumt habe, gibt es mehr zu sehen 😃</p>',17)])])}const f=i(s,[["render",h]]);export{g as __pageData,f as default};
